                vips_exif_set_double, (void *) &xres );
        vips_exif_set_tag( ed, 0, EXIF_TAG_Y_RESOLUTION,
                vips_exif_set_double, (void *) &yres );
        vips_exif_set_tag( ed, 0, EXIF_TAG_RESOLUTION_UNIT,
                vips_exif_set_int, (void *) &unit );

